\title{The Emotional Chromatic Number of Social Networks}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
We introduce and analyze the \emph{emotional chromatic number} of a finite
social network, a variant of the classical graph chromatic number designed to
model the assignment of emotional states to individuals under the constraint that
no two friends share an emotion, together with a psychologically motivated floor
of three categories. Modeling a social network as a finite simple graph $G$ whose
vertices are people and whose edges are friendships, a \emph{proper $k$-coloring}
is an assignment of one of $k$ emotions to each person so that adjacent people
differ; the \emph{chromatic polynomial} $\chi_G(k)$ counts such colorings and is
a polynomial in $k$. We define the emotional chromatic number
$\emochrom(G) = \min\{k \ge 3 : \chi_G(k) > 0\}$ and establish its exact value on
the two fundamental families of networks: for the complete graph (a clique of
mutual friends) $\emochrom(K_n) = \max(n, 3)$, and for the cycle (a friendship
ring) $\emochrom(C_n) = 3$ for all $n \ge 3$. We prove the \emph{six-emotion
window} $3 \le \emochrom(G) \le 6$ for every network colorable with six emotions,
explaining the empirical adequacy of the six basic emotions. Finally we correct a
piece of folklore: bipartite networks are precisely those that admit a
two-emotion coloring, so the honest universal root of the chromatic polynomial
for a network with an edge is at $k = 1$, not $k = 2$. We give algorithms,
numerical demonstrations, and a family of conjectures unifying the invariant with
classical chromatic theory.
\end{abstract}

\maketitle

\section{Introduction}

Graph coloring is among the oldest and most applicable branches of
combinatorics. Its central quantity for a finite simple graph $G = (V, E)$ is the
\emph{chromatic polynomial} $\chi_G(k)$, which counts the number of \emph{proper
$k$-colorings}: functions $c : V \to \{1, \dots, k\}$ with $c(u) \ne c(v)$
whenever $\{u, v\} \in E$. Birkhoff showed $\chi_G$ is a monic polynomial of
degree $|V|$ in $k$, and its least positive integer argument giving a nonzero
value is the \emph{chromatic number} $\chrom(G)$.

This paper reframes coloring as a model of \emph{emotional consistency} in a
social network. Let the vertices of $G$ be people and the edges be friendships.
Identify the $k$ colors with $k$ distinct emotional states; a proper $k$-coloring
is then an assignment of emotions in which no two friends feel the same way. We
call such an assignment \emph{emotionally consistent}. The count of emotionally
consistent assignments over a palette of $k$ emotions is exactly $\chi_G(k)$.

The motivating palette is the set of six \emph{basic emotions} --- happiness,
sadness, anger, fear, disgust, surprise --- long argued to be cross-culturally
universal. Evaluating $\chi_G(6)$ counts the emotionally consistent assignments
over this palette. But the deeper invariant is the smallest palette that works at
all, subject to one modeling decision: a meaningful emotional life requires at
least three categories, since one emotion is uniform affect and two is a mere
binary split. We therefore impose a floor at three.

\begin{definition}[Emotional chromatic number]\label{def:emochrom}
For a finite simple graph $G$, the \emph{emotional chromatic number} is
\[
\emochrom(G) \;=\; \min\{\, k \in \ZZ : k \ge 3 \text{ and } \chi_G(k) > 0 \,\}.
\]
Equivalently, $\emochrom(G) = \max(\chrom(G), 3)$ for every (finitely colorable)
graph $G$.
\end{definition}

\section{Preliminaries}

Throughout, $G = (V, E)$ is a finite simple graph and $n = |V|$.

\begin{definition}[Proper coloring]
For $k \in \NN$, a \emph{proper $k$-coloring} is a map $c : V \to \{1, \dots, k\}$
with $c(u) \ne c(v)$ for every edge $\{u, v\} \in E$.
\end{definition}

\begin{definition}[Chromatic polynomial and number]
$\chi_G(k)$ is the number of proper $k$-colorings of $G$; it is a monic integer
polynomial of degree $n$. The chromatic number is
$\chrom(G) = \min\{k \in \NN : \chi_G(k) > 0\}$.
\end{definition}

\begin{definition}[Bipartite graph]
$G$ is \emph{bipartite} if $V = A \sqcup B$ with every edge having one endpoint in
each part; equivalently $G$ has no odd cycle; equivalently $\chrom(G) \le 2$.
\end{definition}

\begin{lemma}[Monotonicity of colorability]\label{lem:mono}
If $\chi_G(k) > 0$ and $k' \ge k$, then $\chi_G(k') > 0$.
\end{lemma}

\begin{proof}
A proper $k$-coloring is already a proper $k'$-coloring once the palette is
enlarged; the extra colors are unused and every adjacency constraint remains
satisfied.
\end{proof}

Consequently $\{k : \chi_G(k) > 0\} = [\chrom(G), \infty) \cap \ZZ$. Intersecting
with $[3,\infty)$ yields $[\max(\chrom(G),3),\infty)$, whose least element is
$\max(\chrom(G),3)$; this justifies the equivalence in
Definition~\ref{def:emochrom}.

\begin{lemma}[Deletion--contraction]\label{lem:delcon}
For any edge $e \in E$,
$\chi_G(k) = \chi_{G-e}(k) - \chi_{G/e}(k)$, where $G-e$ deletes $e$ and $G/e$
contracts it.
\end{lemma}

\begin{proof}
Proper colorings of $G-e$ split into those giving the endpoints of $e$ different
colors (the proper colorings of $G$) and those giving them equal colors (in
bijection with proper colorings of $G/e$). Rearranging gives the identity.
\end{proof}

\section{Cliques}

\begin{theorem}[Emotional chromatic number of a clique]\label{thm:clique}
For the complete graph $K_n$ with $n \ge 1$, $\emochrom(K_n) = \max(n, 3)$.
\end{theorem}

\begin{proof}
In $K_n$ every two vertices are adjacent, so a proper coloring is injective;
hence a proper $k$-coloring exists iff $k \ge n$, giving $\chrom(K_n) = n$
(concretely $\chi_{K_n}(k) = k(k-1)\cdots(k-n+1)$, positive exactly when
$k \ge n$). By Definition~\ref{def:emochrom},
$\emochrom(K_n) = \max(\chrom(K_n), 3) = \max(n, 3)$.
\end{proof}

\section{Cycles}

\begin{theorem}[Emotional chromatic number of a cycle]\label{thm:cycle}
For the cycle $C_n$ with $n \ge 3$, $\emochrom(C_n) = 3$.
\end{theorem}

\begin{proof}
The chromatic number of a cycle is $2$ for even $n$ (bipartite; alternate two
colors) and $3$ for odd $n$ (the alternation collides upon closing the loop).
Equivalently $\chi_{C_n}(k) = (k-1)^n + (-1)^n(k-1)$, which at $k=2$ equals
$1 + (-1)^n$, i.e. $2$ for even $n$ and $0$ for odd $n$. Taking the emotional
floor, $\emochrom(C_n) = \max(\chrom(C_n), 3) = 3$ in both parities.
\end{proof}

\section{The Six-Emotion Window}

\begin{theorem}[Six-emotion window]\label{thm:window}
If $G$ is a finite graph with $\chrom(G) \le 6$ (equivalently $\chi_G(6) > 0$),
then $3 \le \emochrom(G) \le 6$.
\end{theorem}

\begin{proof}
The lower bound is immediate from Definition~\ref{def:emochrom}. For the upper
bound, $\chrom(G) \le 6$ means $\chi_G(6) > 0$, so $6$ is an admissible palette
size $\ge 3$; hence the defining minimum is at most $6$.
\end{proof}

This explains the empirical adequacy of the six basic emotions: real friendship
networks are sparse and colorable with few colors, so whenever six emotions
suffice for legality the invariant is pinned into $[3, 6]$.

\section{Correcting the Bipartite Folklore}

\begin{theorem}[Two emotions succeed exactly on bipartite networks]\label{thm:bip}
Let $G$ be a finite graph. Then $\chi_G(2) > 0$ if and only if $G$ is bipartite.
Moreover, if $G$ has at least one edge then $\chi_G(1) = 0$.
\end{theorem}

\begin{proof}
A proper $2$-coloring is exactly a partition of $V$ into two color classes with
no edge inside a class --- a bipartition. So $\chi_G(2) > 0$ iff $G$ is bipartite.
A proper $1$-coloring assigns the single color to every vertex, violating the
constraint on any edge; hence $\chi_G(1) = 0$ when $E \ne \emptyset$.
\end{proof}

Thus the universal root of the chromatic polynomial for a network with a
friendship is at $k = 1$, not $k = 2$; bipartite networks are precisely those for
which two emotions first succeed. The emotional floor then lifts every bipartite
network with an edge to $\emochrom = 3$.

\section{Algorithms}

\textbf{Algorithm A (chromatic polynomial by deletion--contraction).}
Recursively apply Lemma~\ref{lem:delcon}, terminating at edgeless graphs where
$\chi_{\overline{K_m}}(k) = k^m$, memoizing on canonical forms.

\smallskip
\textbf{Algorithm B (emotional chromatic number).}
Compute $\chrom(G)$ (least $k$ admitting a proper $k$-coloring) and return
$\max(\chrom(G), 3)$; correctness is Lemma~\ref{lem:mono}. For structured
families the closed forms bypass search: $\emochrom(K_n) = \max(n,3)$,
$\emochrom(C_n) = 3$.

\section{Applications}

The invariant measures the structural demand for affective contrast in a network,
certifies when a six-emotion vocabulary suffices, counts emotionally consistent
labelings via $\chi_G(6)$, and models any ``no two neighbors alike'' allocation
with a minimum-variety floor (frequency assignment, scheduling, register
allocation).

\section{Future Directions}

\begin{conjecture}[The emotional floor is the only correction]
For every finite graph $G$, $\emochrom(G) = \max(\chrom(G), 3)$. The admissible
emotion counts form $[\max(\chrom, 3), \infty)$; the emotional constraint
contributes exactly one thing --- the floor at three.
\end{conjecture}

\begin{conjecture}[Emotional monotonicity under friendship growth]
Adding a friendship raises $\emochrom$ by at most one and removing one lowers it
by at most one, so $\emochrom$ is $1$-Lipschitz with respect to edge edits: a
coloring of the larger graph restricts to the smaller, while a coloring of the
smaller extends across a new edge after recoloring at most one endpoint.
\end{conjecture}

\begin{conjecture}[Sparse networks stay inside the window]
Every network in which each person has at most five friends satisfies
$\emochrom(G) \le 6$; more generally bounded-degree networks have
$\emochrom(G) \le \max(\deg_{\max} + 1, 3)$, since a greedy assignment always
finds a free emotion when the number of colored friends is below the palette
size.
\end{conjecture}

