\bibitem{birkhoff} G. D. Birkhoff, \emph{A determinant formula for the number of
ways of coloring a map}, Ann. of Math., 1912.
\bibitem{read} R. C. Read, \emph{An introduction to chromatic polynomials}, J.
Combin. Theory, 1968.
\bibitem{ekman} P. Ekman, \emph{An argument for basic emotions}, Cognition and
Emotion, 1992.
\end{thebibliography}

