"""
Empirical study: the emotional chromatic number of random sparse social networks
clusters in the six-emotion window [3, 6].
"""
from __future__ import annotations
import random
from typing import Dict, List, Set

Graph = Dict[int, Set[int]]


def erdos_renyi(n: int, p: float, rng: random.Random) -> Graph:
    g: Graph = {v: set() for v in range(n)}
    for u in range(n):
        for v in range(u + 1, n):
            if rng.random() < p:
                g[u].add(v)
                g[v].add(u)
    return g


def is_k_colorable(g: Graph, k: int) -> bool:
    verts = sorted(g)
    color: Dict[int, int] = {}

    def bt(i: int) -> bool:
        if i == len(verts):
            return True
