def emotional_chromatic_number(g: Graph) -> int:
    return max(chromatic_number(g), 3)


def study(trials: int = 100, n: int = 12, p: float = 0.2) -> None:
    rng = random.Random(2024)
    hist: Dict[int, int] = {}
    inside = 0
    for _ in range(trials):
        g = erdos_renyi(n, p, rng)
        e = emotional_chromatic_number(g)
        hist[e] = hist.get(e, 0) + 1
        if 3 <= e <= 6:
            inside += 1
    print(f"Random G(n={n}, p={p}): {trials} networks")
    for e in sorted(hist):
        print(f"  emoChrom={e}: {hist[e]:>3}  {'#' * hist[e]}")
    print(f"Inside [3,6]: {inside}/{trials} = {100*inside/trials:.0f}%")


if __name__ == "__main__":
    study()

"""
Compute the chromatic polynomial by deletion-contraction and read off the
emotional chromatic number from its integer roots.
"""
from __future__ import annotations
from typing import Dict, List, Set, Tuple

Graph = Dict[int, Set[int]]


def poly_add(a: List[int], b: List[int]) -> List[int]:
    n = max(len(a), len(b))
    a = a + [0] * (n - len(a))
    b = b + [0] * (n - len(b))
    return [x + y for x, y in zip(a, b)]


def poly_sub(a: List[int], b: List[int]) -> List[int]:
    return poly_add(a, [-x for x in b])


def poly_eval(a: List[int], k: int) -> int:
    return sum(c * k ** i for i, c in enumerate(a))


def edges_of(g: Graph) -> List[Tuple[int, int]]:
    return [(u, v) for u in g for v in g[u] if u < v]


def chromatic_polynomial(g: Graph) -> List[int]:
    """Return coefficients [c0, c1, ...] of chi_G(k)."""
    edges = edges_of(g)
    if not edges:
        poly = [0] * (len(g) + 1)
        poly[len(g)] = 1  # k^{|V|}
        return poly
    u, v = edges[0]
    g_del: Graph = {w: set(g[w]) for w in g}
    g_del[u].discard(v)
    g_del[v].discard(u)
    g_con: Graph = {w: set(g[w]) for w in g if w != v}
    g_con[u].discard(v)
    for w in list(g_con):
        if v in g_con[w]:
            g_con[w].discard(v)
            if w != u:
                g_con[w].add(u)
                g_con[u].add(w)
    return poly_sub(chromatic_polynomial(g_del), chromatic_polynomial(g_con))


def emotional_chromatic_number(g: Graph) -> int:
    p = chromatic_polynomial(g)
    for k in range(3, len(g) + 1):
        if poly_eval(p, k) > 0:
            return k
    return max(len(g), 3)


if __name__ == "__main__":
    C5: Graph = {v: {(v - 1) % 5, (v + 1) % 5} for v in range(5)}
    print("chi_{C5}(k) coefficients:", chromatic_polynomial(C5))
    for k in range(1, 7):
        print(f"  chi_C5({k}) = {poly_eval(chromatic_polynomial(C5), k)}")
    print("emoChrom(C5) =", emotional_chromatic_number(C5))

